/** git 全局选项：带参数（需跳过下一个 token）与不带参数分开，避免误吞子命令 */
const GIT_OPTS_WITH_ARG = new Set(["-C", "-c", "--git-dir", "--work-tree", "--namespace"]);
const GIT_OPTS_FLAG_ONLY = new Set(["-P", "--no-pager", "--literal-pathspecs", "--no-optional-locks"]);

// 包装形式（cd x && git commit / sh -c "git commit"）无法被首 token 判断覆盖，
// 保留旧正则兜底：误报只是多跑一次门禁（fail-closed），漏报则是绕过
if (!isGitCommit(cmd) && !/\bgit\s+commit\b/.test(cmd)) process.exit(0);

for (let i = 1; i < tokens.length; i++) {
  const t = tokens[i].replace(/^["']|["']$/g, "");
  if (GIT_OPTS_WITH_ARG.has(t)) { i++; continue; } // 跳过带参选项的参数
  if (GIT_OPTS_FLAG_ONLY.has(t) || /^--[\w-]+=/.test(t)) continue; // 无参选项 / --opt=value 内联形式
  return t === "commit"; // 第一个非选项 token 即子命令，立即判定
}
return false;

